def flatten_dict(nested_dict, separator):
    print("Starting dictionary flattening process...")
    flattened_dict = {}
    print(f"Initialized empty flattened dictionary: {flattened_dict}")

    for key, value in nested_dict.items():
        print(f"Processing top-level key: '{key}'")
        if isinstance(value, dict):
            print(f"Value for '{key}' is a dictionary. Entering nested level.")
            for sub_key, sub_value in value.items():
                new_key = f"{key}{separator}{sub_key}"
                print(f"Creating new key: '{new_key}' with value: {sub_value}")
                flattened_dict[new_key] = sub_value
                print(f"Added '{new_key}' to flattened dictionary.")
        else:
            print(f"Value for '{key}' is not a dictionary. Adding directly.")
            flattened_dict[key] = value
            print(f"Added '{key}' to flattened dictionary.")

    print("Finished iterating through all items.")
    print(f"Final flattened dictionary: {flattened_dict}")
    return flattened_dict

