class ToDoList:
    def __init__(self):
        self.tasks = {}
        print("ToDoList initialized.")

    def add_task(self, task_name):
        self.tasks[task_name] = False
        print(f"Task '{task_name}' added.")

    def mark_completed(self, task_name):
        if task_name in self.tasks:
            self.tasks[task_name] = True
            print(f"Task '{task_name}' marked as completed.")
        else:
            print(f"Task '{task_name}' not found.")

    def get_pending_tasks(self):
        pending = [task for task, completed in self.tasks.items() if not completed]
        print("Retrieving pending tasks...")
        if not pending:
            print("No pending tasks.")
        else:
            print(f"Pending tasks: {pending}")
        return pending

todo = ToDoList()
todo.add_task('Buy milk')
todo.add_task('Walk dog')
print("Current tasks added.")
todo.mark_completed('Buy milk')
print("Marking 'Buy milk' as complete.")
pending = todo.get_pending_tasks()
print(f"Result of get_pending_tasks: {pending}")
todo.add_task('Read book')
print("Added another task.")
todo.mark_completed('Code review')
print("Attempted to mark non-existent task.")

